@Singleton
public class LeaderEvents
{
	private static final int CRONDIS_PUZZLE_REGION = 15698;
	private static final int ZEBAK_REGION = 15700;
	private static final int APMEKEN_PUZZLE_REGION = 15186;
	private static final int BABA_REGION = 15188;
	private static final int SCABARAS_PUZZLE_REGION = 14162;
	private static final int KEPHRI_REGION = 14164;
	private static final int HET_PUZZLE_REGION = 14674;
	private static final int AKKHA_REGION = 14676;
	private static final int TOA_VAULT_REGION = 14672;
	private static final int TOA_NEXUS_REGION = 14160;
	private static final int TOA_WARDENS_REGION = 15184;
	private static final int TOA_WARDENS_FINAL_REGION = 15696;
	private static final Pattern RAID_ENTER_MESSAGE =
		Pattern.compile("^You enter the Tombs of Amascut \\([^()]+\\)\\.\\.\\..*");
	private static final String ROOM_FAIL_MESSAGE = "Your party failed to complete the challenge.";
	private static final String RAID_FAIL_MESSAGE = "You failed to survive the Tombs of Amascut.";
	private static final String RAID_ABANDON_MESSAGE = "You abandon the raid and leave the Tombs of Amascut.";

	private static final int TICKS_TO_WAIT_FOR_HET_COMPLETE = 25;
	private static final String HET_SEAL_STRUCK = "The statue has been struck! The seal weakens!";
	private static final String HET_CHALLENGE_COMPLETE = "Challenge complete: Path of Het";

	private static final String APMEKEN_FAIL_DEBRIS = "Damaged roof supports cause some debris to fall on you!";
	private static final String APMEKEN_FAIL_FUMES = "The fumes filling the room suddenly ignite!";
	private static final String APMEKEN_FAIL_CORRUPTION = "Your group is overwhelmed by Amascut's corruption!";

	private int currentRegion = -1;
	private boolean inRaid;
	private final Map<Integer, Integer> orbImpactCycles = new HashMap<>();
	private int hetSealWaitingTick = -1;
	private final ScabarasPuzzleTracker scabarasPuzzles = new ScabarasPuzzleTracker();
	private boolean scabarasSnapshotPending = true;

	private boolean active;

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private SoundManager soundManager;

	public void start()
	{
		if (active)
		{
			return;
		}
		active = true;
		resetState();
		eventBus.register(this);
	}

	public void stop()
	{
		if (!active)
		{
			return;
		}
		active = false;
		eventBus.unregister(this);
		resetState();
	}

	public void resetState()
	{
		currentRegion = -1;
		inRaid = false;
		orbImpactCycles.clear();
		hetSealWaitingTick = -1;
		scabarasPuzzles.reset();
		scabarasSnapshotPending = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING)
		{
			scabarasPuzzles.reset();
			scabarasSnapshotPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		if (local.getLocalLocation() == null || client.getTopLevelWorldView() == null)
		{
			return;
		}

		int region = regionOf(local);
		if (region == -1 && !notInInstance())
		{
			return;
		}
		boolean currentlyInRaid = isRaidRegion(region);
		if (inRaid && !currentlyInRaid)
		{
			soundManager.trigger(ToaEvent.RAID_LEAVE);
		}
		inRaid = currentlyInRaid;
		if (region != currentRegion)
		{
			int previous = currentRegion;
			currentRegion = region;
			onRegionChanged(previous, region);
		}

		if (region == SCABARAS_PUZZLE_REGION)
		{
			Tile[][] tiles = scabarasTiles();
			if (scabarasSnapshotPending && tiles != null)
			{
				scabarasPuzzles.snapshot(tiles);
				scabarasSnapshotPending = false;
			}
			WorldView world = client.getTopLevelWorldView();
			if (world.players() != null)
			{
				for (Player player : world.players())
				{
					if (player != null)
					{
						scabarasPuzzles.observe(player, client.getTickCount());
					}
				}
			}
			scabarasPuzzles.observe(local, client.getTickCount());
			for (ToaEvent failure : scabarasPuzzles.finishTick(client.getTickCount()))
			{
				soundManager.trigger(failure);
			}
		}

		// Process the deadline after transitions, so leaving Het cancels it first.
		if (hetSealWaitingTick > 0 && --hetSealWaitingTick == 0)
		{
			hetSealWaitingTick = -1;
			soundManager.trigger(ToaEvent.HET_ONE_PHASE_FAIL);
		}
	}

	// Puzzle leave sounds only accompany a transition to that path's boss room.
	private void onRegionChanged(int previous, int region)
	{
		ToaEvent leave = puzzleRoomEvent(previous, false);
		if (leave != null && region == bossRegionForPuzzle(previous))
		{
			soundManager.trigger(leave);
		}
		ToaEvent enter = puzzleRoomEvent(region, true);
		if (enter != null)
		{
			soundManager.trigger(enter);
		}
		orbImpactCycles.clear();
		if (region != SCABARAS_PUZZLE_REGION)
		{
			scabarasPuzzles.reset();
			scabarasSnapshotPending = true;
		}

		if (region != HET_PUZZLE_REGION)
		{
			hetSealWaitingTick = -1;
		}

		if (region == TOA_VAULT_REGION)
		{
			int varbitValue = client.getVarbitValue(VarbitID.TOA_VAULT_SARCOPHAGUS);
			soundManager.trigger(determineVaultLootEvent(varbitValue));
		}
	}

	private static ToaEvent puzzleRoomEvent(int region, boolean entering)
	{
		switch (region)
		{
			case CRONDIS_PUZZLE_REGION:
				return entering ? ToaEvent.CRONDIS_ENTER : ToaEvent.CRONDIS_LEAVE;
			case APMEKEN_PUZZLE_REGION:
				return entering ? ToaEvent.APMEKEN_ENTER : ToaEvent.APMEKEN_LEAVE;
			case SCABARAS_PUZZLE_REGION:
				return entering ? ToaEvent.SCABARAS_ENTER : ToaEvent.SCABARAS_LEAVE;
			case HET_PUZZLE_REGION:
				return entering ? ToaEvent.HET_ENTER : ToaEvent.HET_LEAVE;
			default:
				return null;
		}
	}

	private static int bossRegionForPuzzle(int region)
	{
		switch (region)
		{
			case CRONDIS_PUZZLE_REGION:
				return ZEBAK_REGION;
			case APMEKEN_PUZZLE_REGION:
				return BABA_REGION;
			case SCABARAS_PUZZLE_REGION:
				return KEPHRI_REGION;
			case HET_PUZZLE_REGION:
				return AKKHA_REGION;
			default:
				return -1;
		}
	}

	private static boolean isRaidRegion(int region)
	{
		return puzzleRoomEvent(region, true) != null
			|| region == ZEBAK_REGION || region == BABA_REGION
			|| region == KEPHRI_REGION || region == AKKHA_REGION
			|| region == TOA_NEXUS_REGION || region == TOA_VAULT_REGION
			|| region == TOA_WARDENS_REGION || region == TOA_WARDENS_FINAL_REGION;
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() instanceof NPC && client.getGameState() == GameState.LOGGED_IN)
		{
			NPC crocodile = (NPC) event.getActor();
			Player local = client.getLocalPlayer();
			if (local != null && regionOf(local) == CRONDIS_PUZZLE_REGION
				&& crocodile.getWorldView() == client.getTopLevelWorldView()
				&& crocodile.getId() == NpcID.TOA_CRONDIS_CROCODILE
				&& crocodile.getAnimation() == AnimationID.CROC_ATTACK_MERGE)
			{
				// This crocodile's dedicated attack animation is the palm damage signal.
				soundManager.trigger(ToaEvent.CRONDIS_PALM_DAMAGE);
			}
		}

		// Players use the generic slip animation, which must be scoped to Ba-Ba's room.
		if (event.getActor() instanceof Player && !notInInstance()
			&& isBananaSlip(regionOf((Player) event.getActor()), event.getActor().getAnimation()))
		{
			soundManager.trigger(ToaEvent.BABA_BANANA_SLIP);
		}
	}

	static boolean isBananaSlip(int region, int animation)
	{
		return region == BABA_REGION && animation == AnimationID.ROYAL_HUMAN_SLIP_FALL;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (inScabaras())
		{
			scabarasPuzzles.spawned(event.getTile(), event.getGameObject(), client.getTickCount());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (inScabaras())
		{
			scabarasPuzzles.despawned(event.getGameObject(), client.getTickCount());
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (inScabaras() && !event.isConsumed() && event.getId() == ObjectID.TOA_SCABARAS_SIMONSAYS_BUTTON
			&& "Push".equals(event.getMenuOption()))
		{
			scabarasPuzzles.restartSequence();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player local = client.getLocalPlayer();
		if (client.getGameState() == GameState.LOGGED_IN && local != null
			&& event.getActor() instanceof Player && regionOf(local) == HET_PUZZLE_REGION)
		{
			Player player = (Player) event.getActor();
			if (player.getWorldView() != client.getTopLevelWorldView() || regionOf(player) != HET_PUZZLE_REGION)
			{
				return;
			}
			int type = event.getHitsplat().getHitsplatType();
			if (event.getHitsplat().getAmount() > 0
				&& (type == HitsplatID.DAMAGE_ME || type == HitsplatID.DAMAGE_OTHER || type == HitsplatID.DAMAGE_MAX_ME))
			{
				// Light and dark orbs are the puzzle room's only damage source.
				soundManager.trigger(ToaEvent.HET_ORB_DAMAGE);
			}
			return;
		}
		if (!inScabaras() || !(event.getActor() instanceof Player))
		{
			return;
		}
		Player player = (Player) event.getActor();
		if (player.getWorldView() != client.getTopLevelWorldView() || regionOf(player) != SCABARAS_PUZZLE_REGION)
		{
			return;
		}
		ToaEvent puzzle = scabarasPuzzleOf(player);
		int type = event.getHitsplat().getHitsplatType();
		boolean damage = event.getHitsplat().getAmount() > 0
			&& (type == HitsplatID.DAMAGE_ME || type == HitsplatID.DAMAGE_OTHER || type == HitsplatID.DAMAGE_MAX_ME);
		if (damage)
		{
			// Evaluate after all events for this tick, since resets and hitsplats can arrive
			// in either order. A Scarab hit with unchanged puzzle state stays silent.
			scabarasPuzzles.damaged(player, puzzle, client.getTickCount());
		}
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		scabarasPuzzles.forget(event.getPlayer());
	}

	private boolean inScabaras()
	{
		Player local = client.getLocalPlayer();
		return client.getGameState() == GameState.LOGGED_IN && local != null
			&& regionOf(local) == SCABARAS_PUZZLE_REGION;
	}

	private Tile[][] scabarasTiles()
	{
		WorldView world = client.getTopLevelWorldView();
		return world == null || world.getScene() == null ? null : world.getScene().getTiles()[world.getPlane()];
	}

	private ToaEvent scabarasPuzzleOf(Player player)
	{
		LocalPoint location = player.getLocalLocation();
		Tile[][] tiles = scabarasTiles();
		return location == null || tiles == null ? null
			: scabarasPuzzleAt(tiles, location.getSceneX(), location.getSceneY());
	}

	private static ToaEvent scabarasPuzzleAt(Tile[][] tiles, int x, int y)
	{
		Tile tile = tileAt(tiles, x, y);
		if (tile == null)
		{
			return null;
		}
		GroundObject plate = tile.getGroundObject();
		if (plate != null)
		{
			switch (plate.getId())
			{
				case ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_UP:
				case ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN:
				case ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN_PLAYER:
					return ToaEvent.SCABARAS_SEQUENCE_FAIL;
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE1:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE2:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE3:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE4:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE5:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE6:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE7:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE8:
				case ObjectID.TOA_SCABARAS_TOTALTILES_TILE9:
					return ToaEvent.SCABARAS_NUMBER_FAIL;
				case ObjectID.TOA_SCABARAS_LIGHTSOUT_TILE_OFF:
					return null;
			}
		}

		// Recognize the number puzzle beside its tablet too. This only identifies the
		// puzzle; its selected total or a reset must still corroborate any damage.
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				Tile nearby = tileAt(tiles, x + dx, y + dy);
				if (nearby == null || nearby.getGameObjects() == null)
				{
					continue;
				}
				for (GameObject object : nearby.getGameObjects())
				{
					if (object != null && object.getId() == ObjectID.TOA_SCABARAS_TOTALTILES_TABLET)
					{
						return ToaEvent.SCABARAS_NUMBER_FAIL;
					}
				}
			}
		}
		return null;
	}

	private static Tile tileAt(Tile[][] tiles, int x, int y)
	{
		return x >= 0 && x < tiles.length && tiles[x] != null && y >= 0 && y < tiles[x].length
			? tiles[x][y] : null;
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		if (!(event.getActor() instanceof NPC) || notInInstance())
		{
			return;
		}

		NPC orb = (NPC) event.getActor();
		Player local = client.getLocalPlayer();
		if (orb.getId() != NpcID.AKKHA_ENRAGE_ORB
			|| local == null || regionOf(local) != AKKHA_REGION)
		{
			return;
		}

		// The orb itself receives the impact graphic when it hits any player.
		// No player-position check is needed because every teammate's hit should play.
		for (ActorSpotAnim spotAnim : orb.getSpotAnims())
		{
			if (spotAnim.getId() == SpotanimID.AKKHA_ENRAGE_ORB_IMPACT)
			{
				if (recordOrbImpact(orb.getIndex(), spotAnim.getStartCycle()))
				{
					soundManager.trigger(ToaEvent.HET_UNSTABLE_ORB_HIT);
				}
				return;
			}
		}
	}

	boolean recordOrbImpact(int npcIndex, int cycle)
	{
		Integer previousCycle = orbImpactCycles.put(npcIndex, cycle);
		return previousCycle == null || previousCycle != cycle;
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		orbImpactCycles.remove(event.getNpc().getIndex());
	}

	private static ToaEvent determineVaultLootEvent(int varbitValue)
	{
		return (varbitValue & 1) != 0 ? ToaEvent.VAULT_RARE_LOOT : ToaEvent.VAULT_NO_RARE_LOOT;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = event.getMessage();
		String plainMessage = Text.removeTags(message);
		// These messages may arrive before entry or after the exit has loaded.
		if (RAID_ENTER_MESSAGE.matcher(plainMessage).matches())
		{
			soundManager.trigger(ToaEvent.RAID_ENTER);
		}
		else if (plainMessage.startsWith(ROOM_FAIL_MESSAGE))
		{
			soundManager.trigger(ToaEvent.ROOM_FAIL);
		}
		else if (plainMessage.equals(RAID_FAIL_MESSAGE) || plainMessage.equals(RAID_ABANDON_MESSAGE))
		{
			soundManager.trigger(ToaEvent.RAID_FAIL);
		}

		if (notInInstance())
		{
			return;
		}
		Player local = client.getLocalPlayer();
		int region = local == null ? -1 : regionOf(local);

		if (region == SCABARAS_PUZZLE_REGION)
		{
			scabarasPuzzles.chat(Text.removeTags(message));
		}

		// Het seal struck: start countdown to failure if not completed
		if (region == HET_PUZZLE_REGION && message.contains(HET_SEAL_STRUCK))
		{
			hetSealWaitingTick = TICKS_TO_WAIT_FOR_HET_COMPLETE;
		}

		// Het challenge completed: cancel failure detection
		if (message.contains(HET_CHALLENGE_COMPLETE))
		{
			hetSealWaitingTick = -1;
		}

		// Apmeken failures
		if (region == APMEKEN_PUZZLE_REGION && (message.contains(APMEKEN_FAIL_DEBRIS)
			|| message.contains(APMEKEN_FAIL_FUMES)
			|| message.contains(APMEKEN_FAIL_CORRUPTION)))
		{
			soundManager.trigger(ToaEvent.APMEKEN_FAIL);
		}
	}

	private int regionOf(Player player)
	{
		LocalPoint location = player.getLocalLocation();
		if (location == null || notInInstance())
		{
			return -1;
		}
		WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, location);
		return worldPoint == null ? -1 : worldPoint.getRegionID();
	}

	private boolean notInInstance()
	{
		WorldView worldView = client.getTopLevelWorldView();
		return worldView == null || !worldView.isInstance();
	}
}

package com.beepdeep;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.ObjectID;

/** Correlates puzzle state changes with damage; damage alone is not a failure. */
final class ScabarasPuzzleTracker
{
	private static final int SEQUENCE_LENGTH = 5;
	private static final Pattern NUMBER_TARGET = Pattern.compile(
		"The number (?:@[^@]*@)*(\\d+) has been hastily chipped into the stone\\.");
	private static final Pattern COMPLETION = Pattern.compile("Puzzle \\d+ has been completed!");

	private final List<LocalPoint> sequence = new ArrayList<>(SEQUENCE_LENGTH);
	private final Set<LocalPoint> displaying = new HashSet<>();
	private final Map<LocalPoint, GameObject> pressedSequenceTiles = new HashMap<>();
	private final Map<LocalPoint, SequenceStep> sequenceSteps = new HashMap<>();
	private final Map<LocalPoint, GameObject> numberObjects = new HashMap<>();
	private final Map<LocalPoint, Integer> numberValues = new HashMap<>();
	private boolean sequenceReady;
	private boolean sequenceComplete;
	private int lastDisplayTick = -1;
	private int sequenceProgress;
	private final Map<Player, PlayerState> playerStates = new HashMap<>();
	private final Set<Player> numberDamagedPlayers = new HashSet<>();
	private int targetNumber;
	private int numberPeakTotal;
	private int numberResetTick = -1;
	private int numberResetTotal;
	private int numberRemovalTick = -1;
	private int numberRemovedCount;
	private int numberResetCount;
	private boolean numberComplete;
	private boolean numberFailureLatched;

	void reset()
	{
		restartSequence();
		numberObjects.clear();
		numberValues.clear();
		targetNumber = 0;
		numberPeakTotal = 0;
		numberResetTick = -1;
		numberResetTotal = 0;
		numberRemovalTick = -1;
		numberRemovedCount = 0;
		numberResetCount = 0;
		numberDamagedPlayers.clear();
		numberComplete = false;
		numberFailureLatched = false;
		playerStates.clear();
	}

	// Seed active plates once after a scene load or enabling the plugin mid-room.
	void snapshot(Tile[][] tiles)
	{
		for (Tile[] column : tiles)
		{
			if (column == null)
			{
				continue;
			}
			for (Tile tile : column)
			{
				if (tile == null || tile.getGameObjects() == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object != null && (object.getId() == ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN_PLAYER
						|| numberValue(tile) > 0))
					{
						spawned(tile, object, -1);
					}
				}
			}
		}
	}

	void restartSequence()
	{
		sequence.clear();
		displaying.clear();
		pressedSequenceTiles.clear();
		sequenceSteps.clear();
		sequenceReady = false;
		sequenceComplete = false;
		lastDisplayTick = -1;
		sequenceProgress = 0;
		for (PlayerState state : playerStates.values())
		{
			state.sequenceDamage = null;
			state.lastSequenceFailure = null;
			state.lastSequenceStepTick = -1;
		}
	}

	void spawned(Tile tile, GameObject object, int tick)
	{
		LocalPoint point = object.getLocalLocation();
		if (object.getId() == ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN)
		{
			// Completion lights multiple tiles together; demonstration lights one per tick.
			if (lastDisplayTick == tick)
			{
				sequenceComplete = true;
				sequenceReady = false;
				return;
			}
			if (sequenceReady || sequenceComplete || sequence.size() == SEQUENCE_LENGTH)
			{
				restartSequence();
			}
			sequence.add(point);
			displaying.add(point);
			sequenceReady = false;
			lastDisplayTick = tick;
		}
		else if (object.getId() == ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN_PLAYER)
		{
			// Both correct and incorrect input lights this object. It goes dark when
			// vacated, so active lights cannot represent accepted sequence progress.
			if (pressedSequenceTiles.put(point, object) != object && tick >= 0
				&& sequenceReady && !sequenceComplete && sequenceProgress < sequence.size())
			{
				LocalPoint expected = sequence.get(sequenceProgress);
				boolean correct = expected.equals(point);
				sequenceSteps.put(point, new SequenceStep(tick, correct));
				sequenceProgress = correct ? sequenceProgress + 1 : 0;
				if (correct)
				{
					for (PlayerState state : playerStates.values())
					{
						state.lastSequenceFailure = null;
					}
				}
			}
		}
		else if (isNumberLight(object.getId()) && numberValue(tile) > 0)
		{
			if (numberObjects.get(point) != object)
			{
				numberFailureLatched = false;
			}
			numberObjects.put(point, object);
			numberValues.put(point, numberValue(tile));
			numberPeakTotal = Math.max(numberPeakTotal, numberTotal());
		}
	}

	void despawned(GameObject object, int tick)
	{
		LocalPoint point = object.getLocalLocation();
		if (object.getId() == ObjectID.TOA_SCABARAS_SIMONSAYS_TILE_DOWN)
		{
			displaying.remove(point);
			sequenceReady = !sequenceComplete && displaying.isEmpty() && sequence.size() == SEQUENCE_LENGTH;
		}
		else if (pressedSequenceTiles.get(point) == object)
		{
			pressedSequenceTiles.remove(point);
		}
		else if (numberObjects.get(point) == object)
		{
			if (numberRemovalTick != tick)
			{
				numberRemovedCount = 0;
				numberRemovalTick = tick;
			}
			numberRemovedCount++;
			numberPeakTotal = Math.max(numberPeakTotal, numberTotal());
			numberObjects.remove(point);
			numberValues.remove(point);
			if (numberObjects.isEmpty())
			{
				numberResetTick = tick;
				numberResetTotal = numberPeakTotal;
				numberResetCount = numberRemovedCount;
			}
		}
	}

	void observe(Player player, int tick)
	{
		LocalPoint point = player.getLocalLocation();
		if (point == null)
		{
			return;
		}
		PlayerState state = playerStates.computeIfAbsent(player, ignored -> new PlayerState());
		if (sequenceReady && !point.equals(state.previousPoint))
		{
			state.lastSequenceStepTick = tick;
		}
		state.previousPoint = point;
	}

	void forget(Player player)
	{
		playerStates.remove(player);
		numberDamagedPlayers.remove(player);
	}

	void damaged(Player player, ToaEvent puzzle, int tick)
	{
		if (puzzle == ToaEvent.SCABARAS_SEQUENCE_FAIL)
		{
			observe(player, tick);
			PlayerState state = playerStates.get(player);
			if (state != null)
			{
				state.sequenceDamage = player.getLocalLocation();
			}
		}
		else if (puzzle == ToaEvent.SCABARAS_NUMBER_FAIL)
		{
			numberDamagedPlayers.add(player);
		}
	}

	void chat(String message)
	{
		Matcher target = NUMBER_TARGET.matcher(message);
		if (target.find())
		{
			targetNumber = Integer.parseInt(target.group(1));
			numberComplete = false;
		}
		if (COMPLETION.matcher(message).find())
		{
			// The random ordinal does not identify the puzzle, and the observer may be
			// solving a different board. Use shared completion state or pending damage.
			boolean sequenceFinished = sequenceComplete || sequenceProgress == SEQUENCE_LENGTH;
			if (sequenceFinished)
			{
				sequenceComplete = true;
				for (PlayerState state : playerStates.values())
				{
					state.sequenceDamage = null;
				}
			}
			if ((targetNumber > 0 && (numberTotal() == targetNumber || numberResetTotal == targetNumber))
				|| (!sequenceFinished && !numberDamagedPlayers.isEmpty()))
			{
				numberDamagedPlayers.clear();
				numberResetTotal = 0;
				numberPeakTotal = 0;
				numberComplete = true;
			}
		}
		if (message.startsWith("Your party failed to complete the challenge"))
		{
			reset();
		}
	}

	EnumSet<ToaEvent> finishTick(int tick)
	{
		EnumSet<ToaEvent> failures = EnumSet.noneOf(ToaEvent.class);
		for (PlayerState state : playerStates.values())
		{
			SequenceStep step = sequenceSteps.get(state.sequenceDamage);
			boolean recentPress = step != null && step.tick >= tick - 1;
			// A press record retains the expected tile before progress advances or
			// resets. This works whether the light or the damage arrives first.
			boolean wrongTile = recentPress ? !step.correct
				: state.sequenceDamage != null && state.lastSequenceStepTick >= tick - 1
					&& sequenceProgress < sequence.size() && !pressedSequenceTiles.containsKey(state.sequenceDamage)
					&& !sequence.get(sequenceProgress).equals(state.sequenceDamage);
			boolean failure = state.sequenceDamage != null && sequenceReady && !sequenceComplete
				&& !state.sequenceDamage.equals(state.lastSequenceFailure) && wrongTile;
			if (failure)
			{
				failures.add(ToaEvent.SCABARAS_SEQUENCE_FAIL);
				state.lastSequenceFailure = state.sequenceDamage;
			}
			state.sequenceDamage = null;
			if (state.lastSequenceFailure != null && !state.lastSequenceFailure.equals(state.previousPoint))
			{
				state.lastSequenceFailure = null;
			}
		}
		if (failures.contains(ToaEvent.SCABARAS_SEQUENCE_FAIL))
		{
			sequenceProgress = 0;
		}
		if (!numberDamagedPlayers.isEmpty())
		{
			boolean overTarget = targetNumber > 0 && numberPeakTotal > targetNumber;
			boolean incorrectReset = numberResetTick >= tick - 1 && numberResetTotal > 0 && numberResetCount > 1
				&& (targetNumber == 0 || numberResetTotal != targetNumber);
			boolean failure = !numberComplete && !numberFailureLatched && (overTarget || incorrectReset);
			if (failure)
			{
				failures.add(ToaEvent.SCABARAS_NUMBER_FAIL);
				numberResetTotal = 0;
				numberFailureLatched = true;
			}
		}
		numberDamagedPlayers.clear();
		numberPeakTotal = numberTotal();
		sequenceSteps.values().removeIf(step -> step.tick < tick - 1);
		return failures;
	}

	private static final class PlayerState
	{
		private LocalPoint previousPoint;
		private LocalPoint sequenceDamage;
		private LocalPoint lastSequenceFailure;
		private int lastSequenceStepTick = -1;
	}

	private static final class SequenceStep
	{
		private final int tick;
		private final boolean correct;

		private SequenceStep(int tick, boolean correct)
		{
			this.tick = tick;
			this.correct = correct;
		}
	}

	private int numberTotal()
	{
		return numberValues.values().stream().mapToInt(Integer::intValue).sum();
	}

	static int numberValue(Tile tile)
	{
		GroundObject ground = tile == null ? null : tile.getGroundObject();
		if (ground == null)
		{
			return 0;
		}
		switch (ground.getId())
		{
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE1: return 1;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE2: return 2;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE3: return 3;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE4: return 4;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE5: return 5;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE6: return 6;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE7: return 7;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE8: return 8;
			case ObjectID.TOA_SCABARAS_TOTALTILES_TILE9: return 9;
			default: return 0;
		}
	}

	private static boolean isNumberLight(int id)
	{
		switch (id)
		{
			case ObjectID.TOA_SCABARAS_FX03:
			case ObjectID.TOA_SCABARAS_FX05:
			case ObjectID.TOA_SCABARAS_FX06:
			case ObjectID.TOA_SCABARAS_FX07:
			case ObjectID.TOA_SCABARAS_FX08:
			case ObjectID.TOA_SCABARAS_FX09:
			case ObjectID.TOA_SCABARAS_FX10:
			case ObjectID.TOA_SCABARAS_FX11:
			case ObjectID.TOA_SCABARAS_FX12:
				return true;
			default: return false;
		}
	}
}

package com.beepdeep;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.zip.DataFormatException;
import java.util.zip.DeflaterOutputStream;
import java.util.zip.Inflater;

/** Sound-slot-count-prefixed, compressed clipboard format using only Java's standard library. */
final class SoundConfigurationCodec
{
	static final int SOUND_SLOT_COUNT = Arrays.stream(ToaEvent.values())
		.mapToInt(event -> event.getSlots().size()).sum();
	static final String PREFIX = "BD" + SOUND_SLOT_COUNT + ":";
	static final int MAX_CODE_LENGTH = 1_000_000;
	private static final int MAX_PAYLOAD_LENGTH = 2_000_000;
	private static final int MAX_SOURCE_LENGTH = 4096;

	private SoundConfigurationCodec()
	{
	}

	static Export encode(BeepDeepConfig config)
	{
		boolean absolutePaths = false;
		try
		{
			ByteArrayOutputStream compressed = new ByteArrayOutputStream();
			try (DataOutputStream out = new DataOutputStream(new DeflaterOutputStream(compressed)))
			{
				out.writeByte(ToaEvent.values().length);
				for (ToaEvent event : ToaEvent.values())
				{
					// Use stable configuration keys, never enum ordinals.
					out.writeUTF(event.getConfigPrefix());
					out.writeByte(event.isEnabled(config) ? 1 : 0);
					out.writeByte(event.getSlots().size());
					for (ToaEvent.SoundSlot slot : event.getSlots())
					{
						String source = slot.source(config);
						if (source == null)
						{
							source = "";
						}
						validateSource(source);
						absolutePaths |= isAbsolutePath(source);
						out.writeUTF(source);
						out.writeByte(slot.volume(config));
					}
				}
			}
			String code = PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(compressed.toByteArray());
			if (code.length() > MAX_CODE_LENGTH)
			{
				throw new IllegalArgumentException("This sound configuration is too large to share.");
			}
			return new Export(code, absolutePaths);
		}
		catch (IOException e)
		{
			throw new IllegalArgumentException("Could not encode the sound configuration.", e);
		}
	}

	static Imported decode(String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			throw new IllegalArgumentException("Paste a Beep Deep configuration code first.");
		}
		if (text.length() > MAX_CODE_LENGTH)
		{
			throw new IllegalArgumentException("The pasted configuration is too large.");
		}
		String code = text.replaceAll("\\s", "");
		if (!code.startsWith(PREFIX))
		{
			int separator = code.indexOf(':');
			if (code.startsWith("BD") && separator > 2
				&& code.substring(2, separator).matches("[0-9]+"))
			{
				throw new IllegalArgumentException("The code uses a different number of sound slots. This plugin expects "
					+ SOUND_SLOT_COUNT + " slots. Use a compatible plugin version.");
			}
			throw new IllegalArgumentException("Expected a Beep Deep code starting with " + PREFIX + ".");
		}
		try
		{
			byte[] payload = inflate(decodeBase64(code.substring(PREFIX.length())));
			Map<String, ToaEvent> events = new LinkedHashMap<>();
			for (ToaEvent event : ToaEvent.values())
			{
				events.put(event.getConfigPrefix(), event);
			}
			Map<String, Object> settings = new LinkedHashMap<>();
			boolean absolutePaths = false;
			try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(payload)))
			{
				int count = in.readUnsignedByte();
				if (count != events.size())
				{
					throw new IllegalArgumentException("The code is incomplete or uses a different set of events. Use matching plugin versions.");
				}
				for (int i = 0; i < count; i++)
				{
					String key = in.readUTF();
					ToaEvent event = events.remove(key);
					if (event == null)
					{
						throw new IllegalArgumentException("The code contains an unknown or duplicate event assignment.");
					}
					int enabled = in.readUnsignedByte();
					if (enabled > 1)
					{
						throw new IllegalArgumentException("The code contains an invalid event toggle.");
					}
					settings.put(key + "Enabled", enabled == 1);
					if (in.readUnsignedByte() != event.getSlots().size())
					{
						throw new IllegalArgumentException("The code contains an incomplete sound slot assignment.");
					}
					for (int slot = 1; slot <= event.getSlots().size(); slot++)
					{
						String source = in.readUTF();
						validateSource(source);
						absolutePaths |= isAbsolutePath(source);
						settings.put(key + "Sound" + slot, source);
						settings.put(key + "Volume" + slot, readVolume(in));
					}
				}
				if (in.read() != -1)
				{
					throw new IllegalArgumentException("The code contains unexpected extra configuration data.");
				}
			}
			return new Imported(settings, absolutePaths);
		}
		catch (IOException | DataFormatException e)
		{
			throw new IllegalArgumentException("The code is invalid or incomplete. Copy the entire exported code and try again.", e);
		}
	}

	private static byte[] decodeBase64(String encoded)
	{
		try
		{
			return Base64.getUrlDecoder().decode(encoded);
		}
		catch (IllegalArgumentException e)
		{
			throw new IllegalArgumentException("The code is invalid or incomplete. Copy the entire exported code and try again.", e);
		}
	}

	private static byte[] inflate(byte[] compressed) throws DataFormatException
	{
		Inflater inflater = new Inflater();
		try
		{
			inflater.setInput(compressed);
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buffer = new byte[4096];
			while (!inflater.finished())
			{
				int size = inflater.inflate(buffer);
				if (out.size() + size > MAX_PAYLOAD_LENGTH)
				{
					throw new IllegalArgumentException("The pasted configuration expands beyond the size limit.");
				}
				out.write(buffer, 0, size);
				if (size == 0 && !inflater.finished())
				{
					throw new DataFormatException("Incomplete compressed configuration");
				}
			}
			if (inflater.getRemaining() != 0)
			{
				throw new DataFormatException("Extra compressed data");
			}
			return out.toByteArray();
		}
		finally
		{
			inflater.end();
		}
	}

	private static int readVolume(DataInputStream in) throws IOException
	{
		int volume = in.readUnsignedByte();
		if (volume > 100)
		{
			throw new IllegalArgumentException("The code contains a volume outside 0-100%.");
		}
		return volume;
	}

	private static void validateSource(String source)
	{
		if (source.length() > MAX_SOURCE_LENGTH)
		{
			throw new IllegalArgumentException("A sound link or path exceeds the 4096-character limit.");
		}
		for (int i = 0; i < source.length(); i++)
		{
			if (Character.isISOControl(source.charAt(i)))
			{
				throw new IllegalArgumentException("A sound link or path contains an invalid control character.");
			}
		}
	}

	static boolean isAbsolutePath(String source)
	{
		String path = source.trim();
		// Recognize Unix, drive-letter and UNC paths regardless of the importing OS.
		return path.startsWith("/") || path.startsWith("\\")
			|| path.matches("(?i)^[a-z]:[\\\\/].*");
	}

	static final class Export
	{
		final String code;
		final boolean absolutePaths;

		private Export(String code, boolean absolutePaths)
		{
			this.code = code;
			this.absolutePaths = absolutePaths;
		}
	}

	static final class Imported
	{
		final Map<String, Object> settings;
		final boolean absolutePaths;

		private Imported(Map<String, Object> settings, boolean absolutePaths)
		{
			this.settings = Collections.unmodifiableMap(settings);
			this.absolutePaths = absolutePaths;
		}
	}
}

package com.beepdeep;

import java.awt.AWTEvent;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.EventQueue;
import java.awt.FlowLayout;
import java.awt.Frame;
import java.awt.HeadlessException;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;

@Singleton
class SoundConfigurationSharing
{
	private static final String PATH_WARNING =
		"Contains absolute file paths. Those files may not exist on another client; replace them with shared URLs or install the files and update the paths.";
	private final BeepDeepConfig config;
	private final ConfigManager configManager;
	private final AtomicInteger generation = new AtomicInteger();
	private final AtomicInteger remoteRequest = new AtomicInteger();
	private final ThreadLocal<Boolean> changingRemotePermission = ThreadLocal.withInitial(() -> false);
	private volatile boolean active;
	// Dialog state is accessed only on the EDT.
	private JDialog dialog;
	private DialogContent content;
	private int dialogSession;

	@Inject
	SoundConfigurationSharing(BeepDeepConfig config, ConfigManager configManager)
	{
		this.config = config;
		this.configManager = configManager;
	}

	void startUp()
	{
		generation.incrementAndGet();
		configManager.setConfiguration(BeepDeepConfig.GROUP, "openSoundSharingDialog", false);
		active = true;
	}

	void shutDown()
	{
		active = false;
		int stoppedSession = generation.incrementAndGet();
		SwingUtilities.invokeLater(() ->
		{
			if (dialog != null && dialogSession < stoppedSession)
			{
				dialog.dispose();
				dialog = null;
				content = null;
			}
		});
	}

	void onConfigChanged(ConfigChanged event)
	{
		if (!active || !BeepDeepConfig.GROUP.equals(event.getGroup())
			|| Objects.equals(event.getNewValue(), event.getOldValue()))
		{
			return;
		}

		int session = generation.get();
		if ("enableRemoteUrls".equals(event.getKey()))
		{
			if (changingRemotePermission.get())
			{
				return;
			}
			int request = remoteRequest.incrementAndGet();
			if (!"true".equals(event.getNewValue()))
			{
				return;
			}
			JCheckBox checkbox = configCheckbox("Allow remote URLs");
			// Keep network access disabled while the user considers the warning.
			setRemotePermission(event, false);
			SwingUtilities.invokeLater(() ->
			{
				if (!isActive(session) || remoteRequest.get() != request)
				{
					return;
				}
				if (checkbox != null)
				{
					checkbox.setSelected(false);
				}
				boolean allowed = confirm(BeepDeepConfig.REMOTE_WARNING
					+ "\n\nAllow sounds to be downloaded from remote URLs?", "Allow remote URLs", true);
				if (isActive(session) && remoteRequest.get() == request && allowed)
				{
					setRemotePermission(event, true);
					if (checkbox != null)
					{
						checkbox.setSelected(true);
					}
				}
			});
			return;
		}
		if (!"openSoundSharingDialog".equals(event.getKey()) || !"true".equals(event.getNewValue()))
		{
			return;
		}

		JCheckBox checkbox = configCheckbox("Open sharing dialog");
		configManager.setConfiguration(BeepDeepConfig.GROUP, event.getProfile(), "openSoundSharingDialog", false);
		SwingUtilities.invokeLater(() ->
		{
			if (checkbox != null)
			{
				checkbox.setSelected(false);
			}
			if (isActive(session))
			{
				openDialog(session);
			}
		});
	}

	private void setRemotePermission(ConfigChanged event, boolean allowed)
	{
		changingRemotePermission.set(true);
		try
		{
			configManager.setConfiguration(BeepDeepConfig.GROUP, event.getProfile(), "enableRemoteUrls", allowed);
		}
		finally
		{
			changingRemotePermission.remove();
		}
	}

	JCheckBox configCheckbox(String name)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			return null;
		}
		// ConfigPanel doesn't refresh existing checkbox widgets after ConfigChanged.
		// Only adjust the initiating control, identified by its adjacent config label.
		AWTEvent current = EventQueue.getCurrentEvent();
		Component source = current != null && current.getSource() instanceof Component
			? (Component) current.getSource() : null;
		return labeledCheckbox(source, name);
	}

	static JCheckBox labeledCheckbox(Component component, String name)
	{
		if (!(component instanceof JCheckBox) || component.getParent() == null)
		{
			return null;
		}
		for (Component sibling : component.getParent().getComponents())
		{
			if (sibling instanceof JLabel && name.equals(((JLabel) sibling).getText()))
			{
				return (JCheckBox) component;
			}
		}
		return null;
	}

	private boolean isActive(int session)
	{
		return active && generation.get() == session;
	}

	void openDialog(int session)
	{
		if (!isActive(session))
		{
			return;
		}
		if (dialog != null && dialog.isDisplayable() && dialogSession == session)
		{
			dialog.setVisible(true);
			dialog.toFront();
			dialog.requestFocus();
			return;
		}
		if (dialog != null)
		{
			dialog.dispose();
		}
		JDialog opened = createDialog();
		dialog = opened;
		dialogSession = session;
		opened.setContentPane(createDialogContent(session));
		opened.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
		opened.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosing(WindowEvent event)
			{
				saveDraft(session);
			}

			@Override
			public void windowClosed(WindowEvent event)
			{
				if (dialog == opened)
				{
					dialog = null;
					content = null;
				}
			}
		});
		opened.pack();
		opened.setMinimumSize(new Dimension(470, 300));
		opened.setLocationRelativeTo(null);
		opened.setVisible(true);
	}

	private void saveDraft(int session)
	{
		if (isActive(session) && content != null && dialogSession == session)
		{
			configManager.setConfiguration(BeepDeepConfig.GROUP, "soundConfigurationCode", content.code.getText());
		}
	}

	/** Only a fully decoded, whitelisted configuration can reach the settings writer. */
	boolean importCode(String code, Predicate<SoundConfigurationCodec.Imported> confirm)
	{
		SoundConfigurationCodec.Imported imported = SoundConfigurationCodec.decode(code);
		if (!confirm.test(imported))
		{
			return false;
		}
		imported.settings.forEach((key, value) -> configManager.setConfiguration(BeepDeepConfig.GROUP, key, value));
		return true;
	}

	void copyConfiguration(int session)
	{
		if (!isActive(session))
		{
			return;
		}
		try
		{
			SoundConfigurationCodec.Export exported = SoundConfigurationCodec.encode(config);
			if (exported.absolutePaths && !confirm(PATH_WARNING + "\n\nCopy anyway?", "Local file paths", true))
			{
				return;
			}
			if (!isActive(session) || dialog == null || !dialog.isDisplayable())
			{
				return;
			}
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(exported.code), null);
			content.code.setText(exported.code);
			content.code.selectAll();
			setStatus("Copied " + exported.code.length() + " characters."
				+ (exported.code.length() > 2000
					? "\nThis exceeds a typical Discord message. Share it as a text attachment or in multiple parts; import the complete code."
					: "\nShare this code with your party.")
				+ (exported.absolutePaths ? "\n" + PATH_WARNING : ""));
		}
		catch (IllegalArgumentException e)
		{
			setStatus("Copy failed: " + e.getMessage());
		}
		catch (IllegalStateException | HeadlessException | SecurityException e)
		{
			setStatus("Could not access the clipboard. Try again when the clipboard is available.");
		}
	}

	void importConfiguration(String pastedCode, int session)
	{
		if (!isActive(session))
		{
			return;
		}
		try
		{
			boolean applied = importCode(pastedCode, imported ->
			{
				String message = "Replace all event toggles, sound slots and slot volumes?\n"
					+ "Your master volume and remote URL permission stay unchanged."
					+ (imported.absolutePaths ? "\n\n" + PATH_WARNING : "");
				return confirm(message, "Import sound configuration", imported.absolutePaths)
					&& isActive(session) && dialog != null && dialog.isDisplayable();
			});
			if (applied)
			{
				closeDialog();
				showRefreshNotice();
			}
		}
		catch (IllegalArgumentException e)
		{
			setStatus("Import failed: " + e.getMessage() + "\nYour sound settings were not changed.");
		}
	}

	boolean confirm(String message, String title, boolean warning)
	{
		JTextArea text = new JTextArea(message);
		text.setColumns(42);
		text.setEditable(false);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setOpaque(false);
		// Give wrapped text its full height before packing the option pane.
		Dimension initial = text.getPreferredSize();
		text.setSize(initial.width, Short.MAX_VALUE);
		Dimension wrapped = text.getPreferredSize();
		text.setPreferredSize(new Dimension(initial.width, wrapped.height + 16));
		JOptionPane pane = new JOptionPane(text,
			warning ? JOptionPane.WARNING_MESSAGE : JOptionPane.QUESTION_MESSAGE, JOptionPane.OK_CANCEL_OPTION);
		JDialog confirmation = pane.createDialog(dialog, title);
		try
		{
			confirmation.pack();
			confirmation.setMinimumSize(new Dimension(confirmation.getWidth(),
				Math.max(240, confirmation.getHeight() + 24)));
			confirmation.setSize(confirmation.getMinimumSize());
			confirmation.setLocationRelativeTo(dialog);
			confirmation.setVisible(true);
			return Integer.valueOf(JOptionPane.OK_OPTION).equals(pane.getValue());
		}
		finally
		{
			confirmation.dispose();
		}
	}

	JDialog createDialog()
	{
		return new JDialog((Frame) null, "Beep Deep sound sharing", false);
	}

	private void closeDialog()
	{
		if (dialog != null)
		{
			dialog.dispose();
			dialog = null;
			content = null;
		}
	}

	void showRefreshNotice()
	{
		JOptionPane.showMessageDialog(null,
			"Sound configuration imported.\n\nClose and reopen the Beep Deep configuration panel to refresh the displayed settings."
				+ "\n\nYour master volume and Allow remote URLs setting were kept.",
			"Configuration imported", JOptionPane.INFORMATION_MESSAGE);
	}

	private void setStatus(String message)
	{
		if (content != null)
		{
			content.status.setText(message);
			content.status.setCaretPosition(0);
		}
	}

	JPanel createDialogContent(int session)
	{
		content = new DialogContent(session);
		return content;
	}

	private final class DialogContent extends JPanel
	{
		private final JTextArea code = new JTextArea(6, 42);
		private final JTextArea status = new JTextArea(4, 42);

		private DialogContent(int session)
		{
			super(new BorderLayout(0, 8));
			setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
			add(new JLabel("Copy your setup, or paste a Beep Deep code and click Import."), BorderLayout.NORTH);
			code.setText(config.soundConfigurationCode());
			code.setLineWrap(true);
			code.getAccessibleContext().setAccessibleName("Sound configuration code");
			add(new JScrollPane(code), BorderLayout.CENTER);

			JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
			JButton copy = new JButton("Copy configuration");
			copy.addActionListener(event -> copyConfiguration(session));
			actions.add(copy);
			JButton importButton = new JButton("Import configuration");
			importButton.addActionListener(event ->
			{
				saveDraft(session);
				importConfiguration(code.getText(), session);
			});
			actions.add(importButton);
			JButton close = new JButton("Close");
			close.addActionListener(event ->
			{
				saveDraft(session);
				if (dialog != null && dialogSession == session)
				{
					dialog.dispose();
				}
			});
			actions.add(close);
			status.setEditable(false);
			status.setLineWrap(true);
			status.setWrapStyleWord(true);
			status.setOpaque(false);
			status.getAccessibleContext().setAccessibleName("Sharing result");
			JPanel footer = new JPanel(new BorderLayout(0, 8));
			footer.add(actions, BorderLayout.NORTH);
			footer.add(new JScrollPane(status), BorderLayout.CENTER);
			add(footer, BorderLayout.SOUTH);
		}
	}
}

package com.beepdeep;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Resolves local files and caches remote sounds. Disk operations run on the audio
 * executor or OkHttp dispatcher, never on the client thread.
 */
@Singleton
@Slf4j
class SoundFileResolver
{
	static final long MAX_DOWNLOAD_BYTES = 25L * 1024 * 1024;
	private static final File CACHE_DIR =
		RuneLite.RUNELITE_DIR.toPath().resolve("plugin-data").resolve("beep-deep").resolve("cache").toFile();

	private final OkHttpClient httpClient;
	private final File cacheDir;
	private final Map<String, Download> downloads = new HashMap<>();
	private boolean running;

	@Inject
	SoundFileResolver(OkHttpClient httpClient)
	{
		this(httpClient, CACHE_DIR);
	}

	SoundFileResolver(OkHttpClient httpClient, File cacheDir)
	{
		this.httpClient = httpClient;
		this.cacheDir = cacheDir;
	}

	synchronized void startUp()
	{
		running = true;
	}

	synchronized void shutDown()
	{
		running = false;
		for (Download download : downloads.values())
		{
			download.call.cancel();
			download.result.cancel(false);
		}
		downloads.clear();
	}

	static boolean isRemote(String source)
	{
		String normalized = source.toLowerCase(Locale.ROOT);
		return normalized.startsWith("http://") || normalized.startsWith("https://");
	}

	/** Absolute paths may be external; relative paths resolve from .runelite. */
	File localFile(String source) throws IOException
	{
		return localFile(RuneLite.RUNELITE_DIR.toPath(), source);
	}

	static File localFile(Path root, String source) throws IOException
	{
		Path configured = Path.of(source);
		Path resolved;
		if (configured.isAbsolute())
		{
			resolved = configured.toRealPath();
		}
		else
		{
			Path resolvedRoot = root.toRealPath();
			resolved = resolvedRoot.resolve(configured).toRealPath();
			if (!resolved.startsWith(resolvedRoot))
			{
				throw new IOException("Relative sound paths must stay inside .runelite");
			}
		}
		if (!Files.isRegularFile(resolved))
		{
			throw new IOException("Sound paths must point to regular files");
		}
		return resolved.toFile();
	}

	/** Performs a disk stat; call off the client thread. */
	File cachedFile(String url)
	{
		File file = cacheFileFor(url);
		return file.isFile() && file.length() > 0 ? file : null;
	}

	/**
	 * Shares in-flight requests for the same URL. Failed downloads resolve to null,
	 * allowing the next trigger to retry. Shutdown cancels only this plugin's calls.
	 */
	synchronized CompletableFuture<File> download(String url, BooleanSupplier active)
	{
		if (!running || !active.getAsBoolean())
		{
			return CompletableFuture.completedFuture(null);
		}
		Download pending = downloads.get(url);
		if (pending != null)
		{
			return pending.result;
		}

		HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null)
		{
			log.debug("Beep Deep: invalid sound URL {}", url);
			return CompletableFuture.completedFuture(null);
		}

		Call call = httpClient.newCall(new Request.Builder().url(parsed).build());
		Download download = new Download(call);
		downloads.put(url, download);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call failedCall, IOException e)
			{
				log.debug("Beep Deep: sound download failed for {}: {}", url, e.getMessage());
				finish(url, download, null);
			}

			@Override
			public void onResponse(Call responseCall, Response response)
			{
				File file = null;
				try (Response res = response)
				{
					ResponseBody body = res.body();
					if (!res.isSuccessful() || body == null || body.contentLength() > MAX_DOWNLOAD_BYTES)
					{
						log.debug("Beep Deep: rejected sound response for {} (HTTP {})", url, res.code());
						return;
					}
					File target = cacheFileFor(url);
					try (InputStream in = body.byteStream())
					{
						writeToCache(in, target.toPath(), responseCall::isCanceled);
					}
					if (!responseCall.isCanceled())
					{
						file = target;
					}
				}
				catch (IOException e)
				{
					log.debug("Beep Deep: could not cache sound {}: {}", url, e.getMessage());
				}
				finally
				{
					finish(url, download, file);
				}
			}
		});
		return download.result;
	}

	private void finish(String url, Download download, File file)
	{
		synchronized (this)
		{
			downloads.remove(url, download);
		}
		download.result.complete(file);
	}

	/**
	 * Publishes only complete, non-empty downloads. Each writer has its own temp
	 * file so cancellation and retries cannot overwrite another writer's work.
	 */
	static void writeToCache(InputStream in, Path target, BooleanSupplier canceled) throws IOException
	{
		Files.createDirectories(target.getParent());
		Path temporary = Files.createTempFile(target.getParent(), "sound-", ".tmp");
		try
		{
			long total = 0;
			try (OutputStream out = Files.newOutputStream(temporary))
			{
				byte[] buffer = new byte[8192];
				int read;
				while ((read = in.read(buffer)) != -1)
				{
					total += read;
					if (canceled.getAsBoolean() || total > MAX_DOWNLOAD_BYTES)
					{
						throw new IOException("Sound download canceled or exceeded size limit");
					}
					out.write(buffer, 0, read);
				}
			}
			if (total == 0 || canceled.getAsBoolean())
			{
				throw new IOException("Sound download empty or canceled");
			}
			try
			{
				Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			Files.deleteIfExists(temporary);
		}
	}

	private File cacheFileFor(String url)
	{
		return new File(cacheDir, hash(url) + extensionOf(url));
	}

	static String extensionOf(String url)
	{
		HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null)
		{
			return ".wav";
		}
		String path = parsed.encodedPath();
		int dot = path.lastIndexOf('.');
		if (dot > path.lastIndexOf('/'))
		{
			String extension = path.substring(dot);
			if (extension.matches("\\.[a-zA-Z0-9]{1,5}"))
			{
				return extension;
			}
		}
		return ".wav";
	}

	private static String hash(String url)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("SHA-256");
			byte[] digest = md.digest(url.getBytes(StandardCharsets.UTF_8));
			return String.format("%064x", new BigInteger(1, digest));
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 is required by Java", e);
		}
	}

	private static final class Download
	{
		private final Call call;
		private final CompletableFuture<File> result = new CompletableFuture<>();

		private Download(Call call)
		{
			this.call = call;
		}
	}
}

package com.beepdeep;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.nio.file.NoSuchFileException;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Preferences;
import net.runelite.api.SoundEffectVolume;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;

/**
 * Selects and plays the sounds configured for a {@link ToaEvent}.
 *
 * <p>Slots use the typed config bindings in {@link ToaEvent}.
 * One non-empty slot is chosen at random per trigger. Decoding and playback run
 * on a dedicated single background thread because {@link AudioPlayer#play} buffers
 * the whole clip synchronously and must never run on the client thread.
 *
 * <p>Sound slot can be a sound effect ID (numeric), file path, or URL.
 */
@Singleton
@Slf4j
class SoundManager
{
	private static final Consumer<String> IGNORE_ERROR = message -> {};
	private final Client client;
	private final ClientThread clientThread;
	private final PartyService partyService;
	private final AudioPlayer audioPlayer;
	private final SoundFileResolver resolver;
	private final BeepDeepConfig config;
	private final Random random = new Random();

	private volatile ExecutorService executor;

	@Inject
	SoundManager(Client client, ClientThread clientThread, PartyService partyService, AudioPlayer audioPlayer, SoundFileResolver resolver, BeepDeepConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.partyService = partyService;
		this.audioPlayer = audioPlayer;
		this.resolver = resolver;
		this.config = config;
	}

	void startUp()
	{
		shutDown();
		resolver.startUp();
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread thread = new Thread(r, "beep-deep-audio");
			thread.setDaemon(true);
			return thread;
		});
	}

	void shutDown()
	{
		ExecutorService session = executor;
		executor = null;
		resolver.shutDown();
		if (session != null)
		{
			session.shutdownNow();
		}
	}

	/**
	 * Plays a random configured sound for the given event, if the event is
	 * enabled and has at least one non-empty slot. Safe to call from the client
	 * thread; all blocking work is offloaded to the audio executor.
	 */
	void trigger(ToaEvent event)
	{
		if (executor == null || !event.isEnabled(config))
		{
			return;
		}

		List<ToaEvent.SoundSlot> filled = filledSlots(event);
		if (filled.isEmpty())
		{
			return;
		}

		int index = filled.get(random.nextInt(filled.size())).index();
		if (config.enablePartySync() && partyService.isInParty())
		{
			BeepDeepPartyMessage message = new BeepDeepPartyMessage();
			message.setEvent(event.name());
			message.setSlotIndex(index);
			partyService.send(message);
		}

		trigger(event, index);
	}

	void trigger(ToaEvent event, int slotIndex)
	{
		ExecutorService session = executor;
		List<ToaEvent.SoundSlot> all = event.getSlots();
		if (session == null || !event.isEnabled(config) || slotIndex < 0 || slotIndex >= all.size())
		{
			return;
		}

		ToaEvent.SoundSlot slot = all.get(slotIndex);
		String source = normalizeSource(slot.source(config));
		float volume = slot.volume(config) * Math.max(0, Math.min(100, config.masterVolume())) / 100f;
		if (source.isEmpty() || volume == 0)
		{
			return;
		}
		log.debug("Beep Deep: event {} sound {} -> playing '{}' at volume {}", event, slotIndex + 1, source, volume);

		// Try to parse as sound effect ID (must run on client thread)
		Integer soundId = tryParseSoundId(source);
		if (soundId != null)
		{
			playEffect(soundId, volume, IGNORE_ERROR);
			return;
		}

		// File/URL handling (offload to executor for blocking I/O)
		submit(session, () -> resolveAndPlayFile(session, source, volume, IGNORE_ERROR));
	}

	/** Plays the exact selected slot, even for disabled events. Call on the client thread. */
	void preview(ToaEvent event, SoundTestSlot selected, Consumer<String> onError)
	{
		ExecutorService session = executor;
		if (session == null)
		{
			return;
		}
		ToaEvent.SoundSlot slot = event.getSlots().get(selected.getIndex());
		String source = normalizeSource(slot.source(config));
		Consumer<String> report = message ->
		{
			if (executor == session)
			{
				onError.accept(event.getDisplayName() + " / " + selected + "\n\n" + message);
			}
		};
		if (source.isEmpty())
		{
			report.accept("This sound slot is empty. Configure a sound before testing it.");
			return;
		}
		float volume = slot.volume(config) * Math.max(0, Math.min(100, config.masterVolume())) / 100f;
		Integer soundId = tryParseSoundId(source);
		if (volume == 0 || (soundId != null && effectVolumeFromPercent(volume) == SoundEffectVolume.MUTED))
		{
			report.accept("This sound is muted by its slot volume or master volume. Increase the volume to hear it.");
			return;
		}
		if (soundId != null)
		{
			playEffect(soundId, volume, report);
		}
		else
		{
			submit(session, () -> resolveAndPlayFile(session, source, volume, report));
		}
	}

	private void resolveAndPlayFile(ExecutorService session, String source, float volume, Consumer<String> onError)
	{
		// Treat as file path or URL
		if (SoundFileResolver.isRemote(source))
		{
			if (!config.enableRemoteUrls())
			{
				log.debug("Beep Deep: remote URLs are disabled, skipping {}", source);
				onError.accept("Remote URLs are disabled. Enable Allow remote URLs to test this sound.");
				return;
			}

			File cached = resolver.cachedFile(source);
			if (cached != null)
			{
				if (config.enableRemoteUrls())
				{
					playFile(session, cached, volume, onError);
				}
				else
				{
					onError.accept("Remote URLs were disabled before playback.");
				}
				return;
			}

			resolver.download(source, () -> executor == session && config.enableRemoteUrls()).thenAccept(file ->
			{
				submit(session, () ->
				{
					if (!config.enableRemoteUrls())
					{
						onError.accept("Remote URLs were disabled before playback.");
					}
					else if (file == null)
					{
						onError.accept("Could not download the sound: " + source
							+ "\nCheck the URL and connection. Downloads must be non-empty and at most 25 MB.");
					}
					else
					{
						playFile(session, file, volume, onError);
					}
				});
			});
		}
		else
		{
			try
			{
				playFile(session, resolver.localFile(source), volume, onError);
			}
			catch (NoSuchFileException | FileNotFoundException e)
			{
				log.debug("Beep Deep: sound file is missing {}: {}", source, e.getMessage());
				onError.accept("Sound file is missing: " + source
					+ "\nCheck the path. Relative paths start inside .runelite.");
			}
			catch (IOException | IllegalArgumentException e)
			{
				log.debug("Beep Deep: could not resolve sound file {}: {}", source, e.getMessage());
				onError.accept("Could not read sound file: " + source + "\n" + e.getMessage());
			}
		}
	}

	/** Capture the originating session so old callbacks cannot play after a restart. */
	private void submit(ExecutorService session, Runnable task)
	{
		if (executor != session)
		{
			return;
		}
		try
		{
			session.execute(() ->
			{
				if (executor == session && !Thread.currentThread().isInterrupted())
				{
					task.run();
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			log.debug("Beep Deep: audio session stopped before work could be queued");
		}
	}

	private void playFile(ExecutorService session, File file, float volume, Consumer<String> onError)
	{
		if (volume <= 0 || executor != session || Thread.currentThread().isInterrupted())
		{
			return;
		}

		try
		{
			audioPlayer.play(file, gainForVolume(volume));
		}

		catch (UnsupportedAudioFileException | IllegalArgumentException e)
		{
			log.debug("Beep Deep: unsupported sound file {}: {}", file, e.getMessage());
			onError.accept("Unsupported sound file: " + file
				+ "\nUse a supported WAV, AU or AIFF file. MP3 and OGG are not supported.");
		}
		catch (FileNotFoundException e)
		{
			log.debug("Beep Deep: sound file unavailable {}: {}", file, e.getMessage());
			onError.accept("Sound file is missing or inaccessible: " + file + "\nCheck the path and permissions.");
		}
		catch (LineUnavailableException e)
		{
			log.debug("Beep Deep: audio output unavailable: {}", e.getMessage());
			onError.accept("Audio output is unavailable. Check your audio device and try again.");
		}
		catch (Exception e)
		{
			log.debug("Beep Deep: could not play sound file {}: {}", file, e.getMessage());
			onError.accept("Could not play sound file: " + file + "\n" + e.getMessage());
		}
	}

	/**
	 * Plays a RuneScape sound effect by ID.
	 */
	private void playEffect(int soundId, float volumePercent, Consumer<String> onError)
	{
		int effectVolume = effectVolumeFromPercent(volumePercent);
		if (effectVolume == SoundEffectVolume.MUTED)
		{
			return;
		}
		log.debug("Beep Deep: playing sound effect {} at volume {}", soundId, effectVolume);
		clientThread.invoke(() ->
		{
			try
			{
				Preferences preferences = client.getPreferences();
				int gameVolume = preferences.getSoundEffectVolume();
				if (gameVolume == SoundEffectVolume.MUTED)
				{
					client.playSoundEffect(soundId, effectVolume);
					return;
				}

				// RuneLite otherwise overrides the supplied volume with the game setting.
				// The stream is created synchronously, so restore the setting immediately.
				try
				{
					preferences.setSoundEffectVolume(SoundEffectVolume.MUTED);
					client.playSoundEffect(soundId, effectVolume);
				}
				finally
				{
					preferences.setSoundEffectVolume(gameVolume);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Beep Deep: failed to play sound effect {}: {}", soundId, e.getMessage());
				onError.accept("Could not play sound effect " + soundId + ". Try again while logged in.");
			}
		});
	}

	/**
	 * Converts 0-100 volume to the client's 0-127 sound effect range.
	 */
	static int effectVolumeFromPercent(float percent)
	{
		if (percent <= 0)
		{
			return 0;
		}
		return Math.min(127, Math.round(percent * 127f / 100f));
	}

	/**
	 * Tries to parse source as a sound effect ID (numeric).
	 * Returns null if not numeric.
	 */
	static Integer tryParseSoundId(String source)
	{
		if (source == null || source.isEmpty())
		{
			return null;
		}

		String trimmed = source.trim();
		if (!trimmed.matches("^\\d+$"))
		{
			return null;
		}

		try
		{
			return Integer.parseInt(trimmed);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private List<ToaEvent.SoundSlot> filledSlots(ToaEvent event)
	{
		List<ToaEvent.SoundSlot> filled = new ArrayList<>();
		for (ToaEvent.SoundSlot slot : event.getSlots())
		{
			if (!normalizeSource(slot.source(config)).isEmpty())
			{
				filled.add(slot);
			}
		}
		return filled;
	}

	/**
	 * Converts a positive linear percentage into the decibel gain expected by
	 * {@link AudioPlayer}. 100 maps to 0 dB (no attenuation).
	 */
	static float gainForVolume(float volume)
	{
		return (float) (20.0 * Math.log10(volume / 100.0));
	}

	/**
	 * Strips surrounding double quotes from a path if present.
	 * Allows quoted file paths pasted from a file manager.
	 * Numeric strings (sound IDs) are not affected.
	 */
	static String normalizeSource(String source)
	{
		if (source == null)
		{
			return "";
		}
		source = source.trim();
		if (source.length() >= 2 && source.startsWith("\"") && source.endsWith("\""))
		{
			return source.substring(1, source.length() - 1).trim();
		}
		return source;
	}
}

package com.beepdeep;

import java.awt.Dimension;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;

@Singleton
class SoundPreview
{
	private final BeepDeepConfig config;
	private final ConfigManager configManager;
	private final SoundManager sounds;
	private final ClientThread clientThread;
	private final SoundConfigurationSharing sharing;
	private volatile Object session;
	// Dialog state is accessed only on the EDT.
	private JDialog feedback;
	private Object feedbackSession;

	@Inject
	SoundPreview(BeepDeepConfig config, ConfigManager configManager, SoundManager sounds,
		ClientThread clientThread, SoundConfigurationSharing sharing)
	{
		this.config = config;
		this.configManager = configManager;
		this.sounds = sounds;
		this.clientThread = clientThread;
		this.sharing = sharing;
	}

	void startUp()
	{
		configManager.setConfiguration(BeepDeepConfig.GROUP, "playTestSound", false);
		session = new Object();
	}

	void shutDown()
	{
		Object stopped = session;
		session = null;
		SwingUtilities.invokeLater(() ->
		{
			if (feedback != null && feedbackSession == stopped)
			{
				feedback.dispose();
				feedback = null;
			}
		});
	}

	void onConfigChanged(ConfigChanged event)
	{
		Object requestedSession = session;
		if (requestedSession == null || !BeepDeepConfig.GROUP.equals(event.getGroup())
			|| !"playTestSound".equals(event.getKey()) || !"true".equals(event.getNewValue())
			|| Objects.equals(event.getOldValue(), event.getNewValue()))
		{
			return;
		}

		ToaEvent selectedEvent = config.soundTestEvent();
		SoundTestSlot selectedSlot = config.soundTestSlot();
		JCheckBox checkbox = sharing.configCheckbox("Play sound");
		configManager.setConfiguration(BeepDeepConfig.GROUP, event.getProfile(), "playTestSound", false);
		// ConfigPanel does not refresh an existing checkbox when its saved value changes.
		SwingUtilities.invokeLater(() ->
		{
			if (checkbox != null)
			{
				checkbox.setSelected(false);
			}
		});
		clientThread.invoke(() ->
		{
			if (session == requestedSession)
			{
				sounds.preview(selectedEvent, selectedSlot, message -> SwingUtilities.invokeLater(() ->
				{
					if (session == requestedSession)
					{
						showError(message, requestedSession);
					}
				}));
			}
		});
	}

	void showError(String message, Object requestedSession)
	{
		if (feedback != null)
		{
			feedback.dispose();
		}
		JTextArea text = new JTextArea(message);
		text.setColumns(42);
		text.setEditable(false);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setOpaque(false);
		Dimension initial = text.getPreferredSize();
		text.setSize(initial.width, Short.MAX_VALUE);
		text.setPreferredSize(new Dimension(initial.width, text.getPreferredSize().height + 16));
		JOptionPane pane = new JOptionPane(text, JOptionPane.WARNING_MESSAGE);
		feedback = pane.createDialog(null, "Beep Deep sound test");
		feedbackSession = requestedSession;
		feedback.setModal(false);
		feedback.setVisible(true);
	}
}

