	{
		hitsplat(f.local, HitsplatID.DAMAGE_ME, 0);
		hitsplat(f.local, HitsplatID.DAMAGE_MAX_ME, 0);
		hitsplat(f.local, HitsplatID.BLOCK_ME, 0);
		hitsplat(f.local, HitsplatID.HEAL, 5);
