	private List<GameObject> selectThreeNumberPlates()
	{
		List<GameObject> selected = new ArrayList<>();
		for (int x = 1; x <= 3; x++)
		{
			selected.add(numberPlate(x, 2, ObjectID.TOA_SCABARAS_TOTALTILES_TILE9, ObjectID.TOA_SCABARAS_FX12));
