	private static ConfigChanged changed(String group, String key, String oldValue, String newValue)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		event.setKey(key);
		event.setOldValue(oldValue);
		event.setNewValue(newValue);
		return event;
	}

	@Test
	public void rejectsInvalidSourcesOnExport()
	{
		for (String source : new String[]{"a".repeat(4097), "bad\npath.wav"})
		{
			BeepDeepConfig config = new BeepDeepConfig()
			{
				@Override
				public String raidEnterSound1()
				{
					return source;
				}
			};
			try
			{
				SoundConfigurationCodec.encode(config);
				fail("Invalid source was exported");
			}
			catch (IllegalArgumentException e)
			{
				assertTrue(e.getMessage().startsWith("A sound link or path"));
			}
		}
	}

	private static byte[] payload(String code) throws Exception
	{
		try (InflaterInputStream in = new InflaterInputStream(new ByteArrayInputStream(
			Base64.getUrlDecoder().decode(code.substring(SoundConfigurationCodec.PREFIX.length())))))
		{
			return in.readAllBytes();
		}
	}

	private static String compress(byte[] payload) throws Exception
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (DeflaterOutputStream deflater = new DeflaterOutputStream(out))
		{
			deflater.write(payload);
		}
		return SoundConfigurationCodec.PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(out.toByteArray());
	}
}

package com.beepdeep;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SoundDownloadResponseTest
{
	private static final String URL = "https://example.com/sound.aiff?token=1";
	@Rule
	public TemporaryFolder temporary = new TemporaryFolder(new File("build"));
	private OkHttpClient http;
	private Call call;
	private SoundFileResolver resolver;
	private File cache;

	@Before
	public void setUp() throws IOException
	{
		http = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(http.newCall(any())).thenReturn(call);
		cache = temporary.newFolder();
		resolver = new SoundFileResolver(http, cache);
		resolver.startUp();
	}

	@After
	public void tearDown()
	{
		resolver.shutDown();
	}

	@Test
	public void successfulResponsePublishesBytesAndCanBeFoundByUrl() throws Exception
	{
		byte[] bytes = {1, 2, 3, 4};
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		ResponseBody body = ResponseBody.create(MediaType.parse("audio/aiff"), bytes);
		callback().onResponse(call, response(200, body));
		File file = result.join();
		assertNotNull(file);
		assertEquals(cache.getCanonicalFile(), file.getParentFile().getCanonicalFile());
		assertTrue(file.getName().matches("[a-f0-9]{64}\\.aiff"));
		assertArrayEquals(bytes, Files.readAllBytes(file.toPath()));
		assertEquals(file, resolver.cachedFile(URL));
		assertNull(resolver.cachedFile(URL + "2")); // Query is part of the cache key.
		assertEquals(1, cache.list().length);
		ArgumentCaptor<Request> request = ArgumentCaptor.forClass(Request.class);
		verify(http).newCall(request.capture());
		assertEquals(URL, request.getValue().url().toString());
		verify(call, never()).execute();
	}

	@Test
	public void httpErrorClosesBodyDoesNotReadItAndAllowsRetry() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, 0);
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(404, body));
		assertNull(result.join());
		verify(source).close();
		verify(source, never()).inputStream();
		assertEquals(0, cache.list().length);
		assertNotSame(result, resolver.download(URL, () -> true));
		verify(http, times(2)).newCall(any());
	}

	@Test
	public void declaredOversizeBodyIsRejectedBeforeReading() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, SoundFileResolver.MAX_DOWNLOAD_BYTES + 1);
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, body));
		assertNull(result.join());
		verify(source, never()).inputStream();
		verify(source).close();
		assertEquals(0, cache.list().length);
	}

	@Test
	public void emptyBodyDoesNotBecomeACacheHit() throws Exception
	{
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, ResponseBody.create(null, new byte[0])));
		assertNull(result.join());
		assertNull(resolver.cachedFile(URL));
		assertEquals(0, cache.list().length);
	}

	@Test
	public void bodyReadFailureLeavesNoPartialCacheAndCanRetry() throws Exception
	{
		BufferedSource source = mock(BufferedSource.class);
		ResponseBody body = body(source, -1);
		java.io.InputStream input = mock(java.io.InputStream.class);
		when(source.inputStream()).thenReturn(input);
		when(input.read(any(byte[].class))).thenThrow(new IOException("Connection reset"));
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		callback().onResponse(call, response(200, body));
		assertNull(result.join());
		verify(input).close();
		verify(source).close();
		assertEquals(0, cache.list().length);
		assertNotSame(result, resolver.download(URL, () -> true));
	}

	@Test
	public void canceledResponseCannotPublishBytes() throws Exception
	{
		CompletableFuture<File> result = resolver.download(URL, () -> true);
		when(call.isCanceled()).thenReturn(true);
		callback().onResponse(call, response(200, ResponseBody.create(null, new byte[]{1})));
		assertNull(result.join());
		assertEquals(0, cache.list().length);
	}

	private Callback callback()
	{
		ArgumentCaptor<Callback> callback = ArgumentCaptor.forClass(Callback.class);
		verify(call).enqueue(callback.capture());
		return callback.getValue();
	}

	private ResponseBody body(BufferedSource source, long length)
	{
		return new ResponseBody()
		{
			@Override
			public MediaType contentType()
			{
				return null;
			}

			@Override
			public long contentLength()
			{
				return length;
			}

			@Override
			public BufferedSource source()
			{
				return source;
			}
		};
	}

	private Response response(int code, ResponseBody body)
	{
		return new Response.Builder().request(new Request.Builder().url(URL).build())
			.protocol(Protocol.HTTP_1_1).code(code).message("Test response").body(body).build();
	}
}

package com.beepdeep;

import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.Preferences;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SoundEffectPlaybackTest
{
	private Client client;
	private Preferences preferences;
	private BeepDeepConfig config;
	private SoundManager manager;
	private final AtomicInteger gameVolume = new AtomicInteger(96);
	private final AtomicInteger playedVolume = new AtomicInteger(-1);

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		preferences = mock(Preferences.class);
		config = mock(BeepDeepConfig.class);
		when(client.getPreferences()).thenReturn(preferences);
		when(preferences.getSoundEffectVolume()).thenAnswer(invocation -> gameVolume.get());
		doAnswer(invocation ->
		{
			gameVolume.set(invocation.getArgument(0));
			return null;
		}).when(preferences).setSoundEffectVolume(anyInt());
		// Reproduce RuneLite's API: a nonzero game volume overrides the argument.
		doAnswer(invocation ->
		{
			playedVolume.set(gameVolume.get() == 0 ? invocation.getArgument(1) : gameVolume.get());
			return null;
		}).when(client).playSoundEffect(anyInt(), anyInt());
		when(config.crondisEnterEnabled()).thenReturn(true);
		when(config.crondisEnterSound1()).thenReturn("2192");
		when(config.crondisEnterVolume1()).thenReturn(80);
		when(config.masterVolume()).thenReturn(50);
		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));
		manager = new SoundManager(client, clientThread, null, mock(AudioPlayer.class), mock(SoundFileResolver.class), config);
		manager.startUp();
	}

	@After
	public void tearDown()
	{
		manager.shutDown();
	}

	@Test
	public void pluginVolumesApplyWithGameSoundEnabledAndSettingIsRestored()
	{
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(51, playedVolume.get());
		assertEquals(96, gameVolume.get());
		when(config.masterVolume()).thenReturn(100);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(102, playedVolume.get());
		assertEquals(96, gameVolume.get());
		when(config.crondisEnterVolume1()).thenReturn(20);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(25, playedVolume.get());
		assertEquals(96, gameVolume.get());
		verify(preferences, times(3)).setSoundEffectVolume(0);
		verify(preferences, times(3)).setSoundEffectVolume(96);
	}

	@Test
	public void alreadyMutedGameAudioUsesPluginVolumeWithoutChangingSetting()
	{
		gameVolume.set(0);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(51, playedVolume.get());
		assertEquals(0, gameVolume.get());
		verify(preferences, never()).setSoundEffectVolume(anyInt());
	}

	@Test
	public void playbackFailureStillRestoresGameVolume()
	{
		doThrow(new IllegalStateException("Playback failed")).when(client).playSoundEffect(2192, 51);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(96, gameVolume.get());
		verify(preferences).setSoundEffectVolume(0);
		verify(preferences).setSoundEffectVolume(96);
	}

	@Test
	public void mutedOrSubResolutionPluginVolumeDoesNotPlayOrChangeGameSettings()
	{
		when(config.masterVolume()).thenReturn(0);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		when(config.masterVolume()).thenReturn(100);
		when(config.crondisEnterVolume1()).thenReturn(0);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		when(config.masterVolume()).thenReturn(1);
		when(config.crondisEnterVolume1()).thenReturn(1);
		manager.trigger(ToaEvent.CRONDIS_ENTER);
		assertEquals(-1, playedVolume.get());
		assertEquals(96, gameVolume.get());
		verifyNoInteractions(client, preferences);
	}
}

package com.beepdeep;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okio.Timeout;
import org.junit.Test;

import static org.junit.Assert.*;

public class SoundFileResolverLifecycleTest
{
	@Test
	public void duplicateDownloadsShareRequestAndShutdownCancelsIt()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		CompletableFuture<File> result = resolver.download("https://example.com/sound.wav", () -> true);
		assertSame(result, resolver.download("https://example.com/sound.wav", () -> true));
		assertEquals(1, http.calls.size());
		resolver.shutDown();
		assertTrue(http.calls.get(0).isCanceled());
		assertTrue(result.isCancelled());
		assertNull(resolver.download("https://example.com/sound.wav", () -> true).join());
	}

	@Test
	public void failedDownloadCanBeRetried()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		try
		{
			CompletableFuture<File> result = resolver.download("https://example.com/sound.wav", () -> true);
			http.calls.get(0).fail();
			assertNull(result.join());
			assertNotSame(result, resolver.download("https://example.com/sound.wav", () -> true));
			assertEquals(2, http.calls.size());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	@Test
	public void staleFailureDoesNotRemoveDownloadFromNewSession()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		resolver.download("https://example.com/sound.wav", () -> true);
		resolver.shutDown();
		resolver.startUp();
		try
		{
			CompletableFuture<File> current = resolver.download("https://example.com/sound.wav", () -> true);
			http.calls.get(0).fail();
			assertSame(current, resolver.download("https://example.com/sound.wav", () -> true));
			assertEquals(2, http.calls.size());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	@Test
	public void inactiveSessionAndInvalidUrlDoNotStartRequests()
	{
		RecordingClient http = new RecordingClient();
		SoundFileResolver resolver = new SoundFileResolver(http);
		resolver.startUp();
		try
		{
			assertNull(resolver.download("https://example.com/sound.wav", () -> false).join());
			assertNull(resolver.download("https://", () -> true).join());
			assertTrue(http.calls.isEmpty());
		}
		finally
		{
			resolver.shutDown();
		}
	}

	private static final class RecordingClient extends OkHttpClient
	{
		private final List<PendingCall> calls = new ArrayList<>();

		@Override
		public Call newCall(Request request)
		{
			PendingCall call = new PendingCall(request);
			calls.add(call);
			return call;
		}
	}

	private static final class PendingCall implements Call
	{
		private final Request request;
		private Callback callback;
		private boolean canceled;

		private PendingCall(Request request)
		{
			this.request = request;
		}

		void fail()
		{
			callback.onFailure(this, new IOException("Simulated download failure"));
		}

		@Override
		public Request request()
		{
			return request;
		}

		@Override
		public Response execute()
		{
			throw new UnsupportedOperationException("Tests require asynchronous requests");
		}

		@Override
		public void enqueue(Callback callback)
		{
			this.callback = callback;
		}

		@Override
		public void cancel()
		{
			canceled = true;
		}

		@Override
		public boolean isExecuted()
		{
			return callback != null;
		}

		@Override
		public boolean isCanceled()
		{
			return canceled;
		}

		@Override
		public Timeout timeout()
		{
			return new Timeout();
		}

		@Override
		public Call clone()
		{
			return new PendingCall(request);
		}
	}
}

